INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 12, 'theory', 'Quiz: FP libraries and techniques');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 0, 'How does Immer work?', '["It copies the whole object on every call", "It freezes the object and forbids changes", "It gives a proxy draft: you change it and the library builds a new state, copying only the touched nodes", "It stores data in a database"]', 2, 'produce(state, draft => …) records the draft''s changes and returns a new immutable value; if there are no changes, the original reference is returned.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 1, 'What is a lens?', '["A getter and setter pair focused on a part of a structure; lenses can be composed", "A function for magnifying the interface", "A data type for numbers", "An array method"]', 0, 'view reads the part, set replaces it, over applies a function; a lens on the address and a lens on the city glue into a lens on the city in the address.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 2, 'What is the idea behind transducers?', '["To speed up the network", "The transformation is applied to the reducer, so a chain of steps can run in one pass with no intermediate arrays", "To replace promises", "To keep data in a cache"]', 1, 'mapT(f) takes a reducer and returns a reducer that applies f before accumulating; the steps are glued with ordinary composition.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 3, 'What is switchMap for in RxJS?', '["Switching themes", "Combining all streams in parallel", "Synchronous reading", "For each value it starts an inner stream and cancels the previous one, for example a stale search request"]', 3, 'mergeMap runs all inner streams in parallel, concatMap one after another, and switchMap keeps only the latest.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 4, 'How does Validation differ from Either?', '["It doesn''t", "Validation works only with numbers", "Validation accumulates all errors, while Either stops at the first one", "Validation is asynchronous"]', 2, 'To check a form you need to show the user all the errors at once, so the errors are collected in a list.');
